     3	import org.springframework.beans.factory.annotation.Value;
     4	import org.springframework.http.client.SimpleClientHttpRequestFactory;
     5	import org.springframework.stereotype.Component;
     6	import org.springframework.web.client.RestTemplate;
     7	import java.math.BigDecimal;
     8	import java.math.RoundingMode;
     9	import java.util.Map;
    10	
    11	@Component
    12	public class TransLogClient {
    13	    private final RestTemplate restTemplate;
    14	    private final String baseUrl;
    15	
    16	    public TransLogClient(@Value("${translog.url}") String translogUrl) {
    17	        this.baseUrl = translogUrl;
    18	        SimpleClientHttpRequestFactory factory = new SimpleClientHttpRequestFactory();
    19	        factory.setConnectTimeout(2000);
    20	        factory.setReadTimeout(2000);
    21	        this.restTemplate = new RestTemplate(factory);
    22	    }
    23	
    24	    public TransLogQuote getQuote(String zipCode, BigDecimal weightKg, String service) {
    25	        try {
    26	            int weightGrams = weightKg.multiply(new BigDecimal("1000")).intValue();
    27	
    28	            String url = baseUrl + "/v2/quote?zip=" + zipCode + "&weight_g=" + weightGrams + "&service=" + service;
    29	
    30	            @SuppressWarnings("unchecked")
    31	            Map<String, Object> response = restTemplate.getForObject(url, Map.class);
    32	
    33	            if (response != null && response.containsKey("error")) {
    34	                String error = (String) response.get("error");
    35	                if ("ZIP_NOT_SERVED".equals(error)) {
    36	                    return new TransLogQuote(false, null, null);
    37	                }
    38	                throw new RuntimeException("TransLog error: " + error);
    39	            }
    40	
    41	            if (response == null) {
    42	                return new TransLogQuote(false, null, null);
    43	            }
    44	
    45	            Integer priceCents = (Integer) response.get("price_cents");
    46	            Integer etaHours = (Integer) response.get("eta_hours");
    47	
    48	            BigDecimal price = new BigDecimal(priceCents).divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
    49	            int days = (int) Math.ceil(etaHours / 24.0);
    50	
    51	            return new TransLogQuote(true, price, days);
    52	        } catch (Exception e) {
    53	            return new TransLogQuote(false, null, null);
    54	        }
    55	    }
    56	
    57	    public static class TransLogQuote {
    58	        private final boolean available;
    59	        private final BigDecimal price;
    60	        private final Integer deliveryDays;
    61	
    62	        public TransLogQuote(boolean available, BigDecimal price, Integer deliveryDays) {
    63	            this.available = available;
    64	            this.price = price;
    65	            this.deliveryDays = deliveryDays;
    66	        }
    67	
    68	        public boolean isAvailable() { return available; }
    69	        public BigDecimal getPrice() { return price; }
    70	        public Integer getDeliveryDays() { return deliveryDays; }
    71	    }
    72	}
