    23	        TransLogClient.TransLogQuote quote = transLogClient.getQuote(request.getZipCode(), totalWeightKg, "STD");
    24	
    25	        if (!quote.isAvailable()) {
    26	            throw new RuntimeException("TransLog unavailable or ZIP not served");
    27	        }
    28	
    29	        int extraDays = switch (request.getRegion()) {
    30	            case "NORTH" -> 3;
    31	            case "NORTHEAST" -> 2;
    32	            default -> 0;
    33	        };
